//! Binary BCH codes, shortened: the outer code of DVB-S2 (`com_systems::dvbs2`).
//!
//! # Model
//!
//! In the Galois field $\mathrm{GF}(2^{m})$ generated by a primitive element $\alpha$
//! (root of a primitive polynomial $p(x)$), the narrow-sense BCH code of designed
//! distance $2t + 1$ has the generator polynomial
//!
//! $$
//! g(x) = \operatorname{lcm}\left(m_{1}(x), m_{3}(x), \dots, m_{2t-1}(x)\right),
//! $$
//!
//! with $m_{i}$ the minimal polynomial of $\alpha^{i}$ (Lin & Costello, ch. 6). The code
//! of length $2^{m} - 1$ is shortened to $n$ bits by fixing its first information bits
//! to zero. The encoder is systematic: the $k$ message bits $m_{k-1}, \dots, m_{0}$ (the
//! highest degree first, in transmission order) followed by the $n - k$ coefficients of
//! $x^{n-k} m(x) \bmod g(x)$. The decoder computes the syndromes $S_{j} = r(\alpha^{j})$,
//! the error-locator polynomial by the Berlekamp–Massey algorithm and its roots by a
//! Chien search over the $n$ positions; it corrects up to $t$ errors and reports a
//! failure beyond (when the locator has fewer roots than its degree). The field
//! arithmetic is that of [`com_math::gf2m`].
//!
//! # Examples
//! ```
//! use com_fec::bch::Bch;
//! // the (15, 7) BCH code, t = 2, of GF(16) with p(x) = 1 + x + x⁴
//! let code = Bch::new(4, 0b1_0011, 2, 15)?;
//! assert_eq!(code.k(), 7);
//! assert_eq!(code.generator(), &[1, 0, 0, 0, 1, 0, 1, 1, 1]);   // 1 + x⁴ + x⁶ + x⁷ + x⁸
//! let msg = [1, 0, 1, 1, 0, 0, 1];
//! let mut c = code.encode(&msg)?;
//! c[2] ^= 1;
//! c[11] ^= 1;
//! let (decoded, corrected) = code.decode(&c)?;
//! assert_eq!((decoded, corrected), (msg.to_vec(), Some(2)));
//! # Ok::<(), com_core::Error>(())
//! ```
//!
//! # References
//!
//! 1. S. Lin and D. J. Costello, *Error Control Coding*, 2nd ed., Pearson, 2004, ch. 6.
//! 2. ETSI EN 302 307-1 V1.4.1, *Digital Video Broadcasting (DVB); Second generation
//!    framing structure, channel coding and modulation systems (DVB-S2)*, 2014,
//!    § 5.3.1.

use crate::algebraic::{berlekamp_massey, chien_search};
use crate::block::expect_len;
use com_core::{Result, ensure};
use com_math::gf2::poly_mul;
use com_math::gf2m::Field;

/// A shortened binary BCH code (see the module).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Bch {
    field: Field,
    t: usize,
    n: usize,
    /// $g(x)$, lowest degree first.
    generator: Vec<u8>,
}

impl Bch {
    /// The code of $\mathrm{GF}(2^{m})$ with the primitive polynomial `poly` (bit $i$ the
    /// coefficient of $x^{i}$), correcting `t` errors, shortened to `n` bits.
    ///
    /// # Errors
    /// [`com_core::Error::Config`] for a polynomial that is not primitive, or a length
    /// that leaves no message bit or exceeds $2^{m} - 1$.
    pub fn new(m: u32, poly: u32, t: usize, n: usize) -> Result<Bch> {
        let field = Field::new(m, poly)?;
        ensure(t >= 1, || "BCH: t must be at least 1".into())?;
        let mut generator = vec![1u8];
        let mut used: Vec<Vec<u8>> = Vec::new();
        for i in (1..2 * t).step_by(2) {
            let mi = field.minimal_polynomial(i);
            if !used.contains(&mi) {
                generator = poly_mul(&generator, &mi);
                used.push(mi);
            }
        }
        let r = generator.len() - 1;
        ensure(n <= field.order() && n > r, || {
            format!("BCH: the length {n} must exceed the {r} parity bits and not exceed {}", field.order())
        })?;
        Ok(Bch { field, t, n, generator })
    }

    /// Codeword length $n$.
    pub fn n(&self) -> usize {
        self.n
    }

    /// Message length $k = n - \deg g$.
    pub fn k(&self) -> usize {
        self.n + 1 - self.generator.len()
    }

    /// Errors corrected $t$.
    pub fn t(&self) -> usize {
        self.t
    }

    /// The generator polynomial $g(x)$, lowest degree first.
    pub fn generator(&self) -> &[u8] {
        &self.generator
    }

    /// The codeword of $k$ message bits: the message, then the parity bits (highest
    /// degree first).
    ///
    /// # Errors
    /// [`com_core::Error::Shape`] for another number of bits.
    pub fn encode(&self, msg: &[u8]) -> Result<Vec<u8>> {
        expect_len(msg.len(), self.k(), "bits")?;
        let r = self.generator.len() - 1;
        // a shift register of r bits in 64-bit words, bit r - 1 the highest degree
        let words = r.div_ceil(64);
        let mut g = vec![0u64; words];
        for (d, &b) in self.generator[..r].iter().enumerate() {
            if b == 1 {
                g[d / 64] |= 1 << (d % 64);
            }
        }
        let mut reg = vec![0u64; words];
        let top = r - 1;
        for &b in msg {
            let fb = ((reg[top / 64] >> (top % 64)) & 1) as u8 ^ (b & 1);
            // shift left by one
            for w in (0..words).rev() {
                let carry = if w > 0 { reg[w - 1] >> 63 } else { 0 };
                reg[w] = (reg[w] << 1) | carry;
            }
            if r % 64 != 0 {
                reg[words - 1] &= (1u64 << (r % 64)) - 1;
            }
            if fb == 1 {
                for (x, y) in reg.iter_mut().zip(&g) {
                    *x ^= y;
                }
            }
        }
        let mut c: Vec<u8> = msg.iter().map(|b| b & 1).collect();
        c.extend((0..r).rev().map(|d| ((reg[d / 64] >> (d % 64)) & 1) as u8));
        Ok(c)
    }

    /// Decode $n$ hard bits: the message and the number of corrected errors (`None` if
    /// the word has more errors than the code corrects and they were detected; the
    /// message bits are then returned as received).
    ///
    /// # Errors
    /// [`com_core::Error::Shape`] for another number of bits.
    pub fn decode(&self, r: &[u8]) -> Result<(Vec<u8>, Option<usize>)> {
        expect_len(r.len(), self.n, "bits")?;
        let f = &self.field;
        let n = self.n;
        let two_t = 2 * self.t;
        // syndromes S_j = r(α^j), position i carrying x^{n-1-i}
        let mut s = vec![0u32; two_t + 1];
        for (i, &b) in r.iter().enumerate() {
            if b & 1 == 1 {
                let e = n - 1 - i;
                for (j, sj) in s.iter_mut().enumerate().skip(1) {
                    *sj ^= f.pow(j * e);
                }
            }
        }
        let k = self.k();
        let msg = r[..k].iter().map(|b| b & 1).collect::<Vec<u8>>();
        if s.iter().all(|&v| v == 0) {
            return Ok((msg, Some(0)));
        }
        // Berlekamp–Massey on S_1 … S_{2t}; at most t errors
        let (lambda, _) = berlekamp_massey(f, &s[1..]);
        let degree = lambda.len() - 1;
        if degree > self.t {
            return Ok((msg, None));
        }
        // Chien search: position i is in error if Λ(α^{-(n-1-i)}) = 0; as many roots as
        // the degree of Λ
        let order = f.order();
        let roots = chien_search(f, &lambda, n, |i| (n - 1 - i) % order);
        if roots.len() != degree {
            return Ok((msg, None));
        }
        let mut out: Vec<u8> = r.iter().map(|b| b & 1).collect();
        for &i in &roots {
            out[i] ^= 1;
        }
        let found = roots.len();
        out.truncate(k);
        Ok((out, Some(found)))
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use com_core::rng::Rng;

    #[test]
    fn the_generators_of_dvb_s2_are_the_products_of_the_published_polynomials() {
        // ETSI EN 302 307-1, Table 6a: g1 … g12 of the normal FECFRAME, GF(2^16)
        let table6a: [&[usize]; 12] = [
            &[0, 2, 3, 5, 16],
            &[0, 1, 4, 5, 6, 8, 16],
            &[0, 2, 3, 4, 5, 7, 8, 9, 10, 11, 16],
            &[0, 2, 4, 6, 9, 11, 12, 14, 16],
            &[0, 1, 2, 3, 5, 8, 9, 10, 11, 12, 16],
            &[0, 2, 4, 5, 7, 8, 9, 10, 12, 13, 14, 15, 16],
            &[0, 2, 5, 6, 8, 9, 10, 11, 13, 15, 16],
            &[0, 1, 2, 5, 6, 8, 9, 12, 13, 14, 16],
            &[0, 5, 7, 9, 10, 11, 16],
            &[0, 1, 2, 5, 7, 8, 10, 12, 13, 14, 16],
            &[0, 2, 3, 5, 9, 11, 12, 13, 16],
            &[0, 1, 5, 6, 7, 9, 11, 12, 16],
        ];
        let f = Field::new(16, 0b1_0000_0000_0010_1101).unwrap();
        for (i, g) in table6a.iter().enumerate() {
            let mut p = vec![0u8; 17];
            for &d in *g {
                p[d] = 1;
            }
            assert_eq!(f.minimal_polynomial(2 * i + 1), p, "g{}", i + 1);
        }
    }

    #[test]
    fn up_to_t_errors_are_corrected_and_more_are_mostly_detected() {
        // the short DVB-S2 code of rate 1/2: GF(2^14), t = 12, (7200, 7032)
        let code = Bch::new(14, 0b100_0000_0010_1011, 12, 7200).unwrap();
        assert_eq!(code.k(), 7032);
        let mut rng = Rng::new(4);
        for errors in [0, 1, 5, 12] {
            let msg: Vec<u8> = (0..code.k()).map(|_| rng.bit()).collect();
            let mut c = code.encode(&msg).unwrap();
            for _ in 0..errors {
                let p = rng.below(c.len());
                c[p] ^= 1;
            }
            let (m, n) = code.decode(&c).unwrap();
            if errors <= 12 && n.is_some() {
                assert_eq!(m, msg);
            }
        }
        // exactly t distinct errors
        let msg: Vec<u8> = (0..code.k()).map(|_| rng.bit()).collect();
        let mut c = code.encode(&msg).unwrap();
        for p in [3, 100, 2000, 5000, 7031, 7032, 7100, 7199, 1, 2, 4000, 6000] {
            c[p] ^= 1;
        }
        assert_eq!(code.decode(&c).unwrap(), (msg, Some(12)));
    }
}
